+              Cancel
+            </Button>
+          </Stack>
+        </Box>
+      ) : (
+        <Stack direction={"row"} spacing={1} sx={{ mt: 1 }}>
+          <Button
+            size={"small"}
+            variant={"contained"}
+            disabled={applying}
+            onClick={() => setConfirming(true)}
+            aria-label={"Apply to outline"}
+          >
+            Apply to outline
+          </Button>
+          <Button
+            size={"small"}
+            disabled={applying}
+            onClick={onDiscard}
+            aria-label={"Discard outline revision"}
+          >
+            Discard
+          </Button>
+        </Stack>
+      )}
+    </Box>
+  );
+}
